<?php use Hls\Http\View as V; ?><form class="panel form-grid" method="get"><label>Mulai<input type="date" name="start" value="<?= V::escape($start) ?>"></label><label>Sampai<input type="date" name="end" value="<?= V::escape($end) ?>"></label><label>Cabang<select name="branch_id"><option value="0">Semua cabang dalam akses</option><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>" <?= $branch_id===(int)$b['id']?'selected':'' ?>><?= V::escape($b['code'].' - '.$b['name']) ?></option><?php endif; endforeach ?></select></label><button class="button primary">Terapkan</button></form><div class="kpi-grid"><?php foreach([['Total Pendapatan',$income],['Total Beban',$cost],['Laba/Rugi Bersih',$net]] as $k): ?><article class="panel kpi-card"><span class="kpi-label"><?= V::escape($k[0]) ?></span><strong class="kpi-value"><?= \Hls\Http\View::money($k[1]) ?></strong></article><?php endforeach ?><article class="panel kpi-card"><span class="kpi-label">Margin Laba Bersih</span><strong class="kpi-value"><?= $margin===null?'N/A':number_format($margin,2,',','.').'%' ?></strong></article></div><section class="panel"><h2>Rincian Pendapatan</h2><div class="table-wrap"><table><thead><tr><th>Kelompok</th><th>Nominal</th></tr></thead><tbody><?php foreach($revenue as $r): ?><tr><td><?= V::escape($r['category']) ?></td><td><?= \Hls\Http\View::money($r['amount']) ?></td></tr><?php endforeach ?><?php if(!$revenue): ?><tr><td colspan="2">Belum ada pendapatan di periode ini.</td></tr><?php endif ?></tbody></table></div></section><section class="panel"><h2>Rincian Beban Operasional</h2><div class="table-wrap"><table><thead><tr><th>Kategori</th><th>Nominal</th></tr></thead><tbody><?php foreach($expenses as $e): ?><tr><td><?= V::escape($e['category']) ?></td><td><?= \Hls\Http\View::money($e['amount']) ?></td></tr><?php endforeach ?><?php if(!$expenses): ?><tr><td colspan="2">Belum ada beban operasional di periode ini.</td></tr><?php endif ?></tbody></table></div><p class="field-hint">Tagihan supplier dan pembayaran utang tidak dimasukkan sebagai beban otomatis karena klasifikasi akuntansinya belum tersedia.</p></section>